INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(700, 'blue', '/bluː/', 'adjective', '{"zh-TW":["藍色的；憂鬱的"],"en":["the color of the sky on a clear day","having the color of the sky; sad"]}', NULL, 'out of the blue / feeling blue; out of the blue (突然) / feel blue', '[{"en":"The sky is bright blue today.","zh-TW":"今天天空是亮藍色的。"},{"en":"The news came out of the blue.","zh-TW":"這消息來得很突然。"},{"en":"The sky is clear and blue.","zh-TW":"天空清澈湛藍。"}]', NULL, NULL, 1, 700, NULL),
(701, 'blue chip', '/bluː tʃɪp/', 'adjective', '{"zh-TW":["績優的；藍籌的"],"en":["relating to a company that is well-established and financially stable"]}', NULL, 'blue chip company / blue chip investment', '[{"en":"Pension funds typically hold blue chip stocks for stable long-term returns.","zh-TW":"養老基金通常持有績優股票以獲得穩定的長期回報。"},{"en":"Blue chip companies are regarded as low-risk investments.","zh-TW":"績優公司被視為低風險投資。"}]', '{"noun":"blue chip stock"}', NULL, 3, 701, NULL),
(702, 'blue ocean strategy', '/bluː ˈoʊʃən ˈstrætədʒi/', 'noun', '{"zh-TW":["藍海策略"],"en":["a strategy of creating uncontested market space rather than competing"]}', NULL, 'pursue a blue ocean strategy / blue ocean vs red ocean', '[{"en":"The startup found a blue ocean by targeting an entirely new customer segment.","zh-TW":"新創公司通過針對全新客戶群找到了藍海。"},{"en":"Blue ocean strategy focuses on value innovation rather than competition.","zh-TW":"藍海策略著重於價值創新而非競爭。"}]', NULL, NULL, 5, 702, NULL),
(703, 'blue-chip stock', '/bluː tʃɪp stɒk/', 'noun', '{"zh-TW":["藍籌股"],"en":["shares in a large, reputable, and financially stable company"]}', NULL, 'invest in blue-chip stocks / blue-chip stock performance', '[{"en":"Blue-chip stocks provide stable dividends and lower volatility.","zh-TW":"藍籌股提供穩定的股息和較低的波動性。"},{"en":"Institutional investors favor blue-chip stocks for long-term portfolios.","zh-TW":"機構投資者青睞藍籌股用於長期投資組合。"}]', NULL, NULL, 5, 703, NULL),
(704, 'blueprint', '/ˈbluːprɪnt/', 'noun', '{"zh-TW":["藍圖；計畫","藍圖；詳細計畫"],"en":["a detailed plan or scheme","a detailed plan or design"]}', '{"root":{"text":"blue","meaning":"blue (藍色)"},"suffix":{"text":"print","meaning":"print (印刷)"},"logic":"藍色印刷的設計圖，即「藍圖」。"}', 'blueprint for success / strategic blueprint; blueprint for success / provide a blueprint', '[{"en":"The CEO presented a blueprint for the company''s future.","zh-TW":"執行長提出了公司未來的藍圖。"},{"en":"This plan serves as a blueprint for similar projects.","zh-TW":"此計畫可作為類似專案的藍圖。"},{"en":"This is our blueprint for expansion.","zh-TW":"這是我們的擴張藍圖。"},{"en":"The report provides a blueprint for reform.","zh-TW":"報告提供了改革的藍圖。"}]', '{"noun":"blueprint"}', NULL, 3, 704, 828),
(705, 'bluetooth', '/ˈbluːtuːθ/', 'noun', '{"zh-TW":["藍牙"],"en":["wireless technology for short-range data exchange"]}', NULL, 'bluetooth connection / bluetooth speaker', '[{"en":"Connect your headphones via Bluetooth.","zh-TW":"透過藍牙連接你的耳機。"},{"en":"Is your Bluetooth turned on?","zh-TW":"你的藍牙開了嗎？"}]', NULL, NULL, 3, 705, NULL),
(706, 'board', '/bɔːrd/', 'noun', '{"zh-TW":["董事會；委員會","板"],"en":["a group of people who manage an organization","to get on a vehicle"]}', '{"root":{"text":"board","meaning":"plank/table (桌板)"},"logic":"圍著桌子開會的人，即「董事會」。"}', 'board of directors / board meeting / on board', '[{"en":"The board of directors approved the acquisition.","zh-TW":"董事會批准了收購案。"},{"en":"All passengers must board 30 minutes before departure.","zh-TW":"所有乘客必須在起飛前30分鐘登機。"}]', NULL, NULL, 2, 706, 279),
(707, 'board meeting', '/bɔːrd ˈmiːtɪŋ/', 'noun', '{"zh-TW":["董事會會議"],"en":["a formal meeting of a company''s board of directors"]}', NULL, 'attend a board meeting / quarterly board meeting', '[{"en":"The board meeting approved the expansion strategy.","zh-TW":"董事會會議批准了擴張策略。"},{"en":"Minutes of the board meeting are distributed within 48 hours.","zh-TW":"董事會會議記錄在48小時內分發。"}]', NULL, NULL, 5, 707, NULL),
(708, 'board of directors', '/bɔːrd əv dɪˈrektərz/', 'noun', '{"zh-TW":["董事會"],"en":["the governing body of a corporation elected by shareholders"]}', NULL, 'board of directors meeting / sit on the board of directors', '[{"en":"The board of directors approved the acquisition.","zh-TW":"董事會批准了收購計劃。"},{"en":"She was elected to the board of directors last month.","zh-TW":"她上個月當選為董事會成員。"}]', '{"singular":"board member"}', NULL, 5, 708, NULL),
(709, 'board resolution', '/bɔːrd ˌrezəˈluːʃən/', 'noun', '{"zh-TW":["董事會決議"],"en":["a formal decision made and documented by a company''s board of directors"]}', NULL, 'pass a board resolution / board resolution required', '[{"en":"A board resolution was passed to approve the acquisition.","zh-TW":"通過了一項董事會決議以批准此次收購。"},{"en":"All major financial commitments require a board resolution.","zh-TW":"所有重大財務承諾都需要董事會決議。"}]', NULL, NULL, 5, 709, NULL),
(710, 'boarding pass', '/ˈbɔːrdɪŋ pæs/', 'noun', '{"zh-TW":["登機證"],"en":["a document allowing a passenger to board a plane"]}', NULL, 'print a boarding pass / mobile boarding pass', '[{"en":"Please have your boarding pass ready at the gate.","zh-TW":"請在登機口備好登機證。"},{"en":"You can download your boarding pass to your phone.","zh-TW":"您可以把登機證下載到手機。"}]', NULL, NULL, 5, 710, NULL),
(711, 'boardroom', '/ˈbɔːrdruːm/', 'noun', '{"zh-TW":["董事會會議室；會議室"],"en":["a room where a board of directors meets"]}', NULL, 'boardroom meeting / boardroom presentation', '[{"en":"The quarterly review was held in the boardroom.","zh-TW":"季度審查在董事會會議室舉行。"},{"en":"A major decision was announced from the boardroom.","zh-TW":"一項重大決定從董事會會議室宣布。"}]', NULL, NULL, 3, 711, NULL),
(712, 'boat', '/boʊt/', 'noun', '{"zh-TW":["船；小艇"],"en":["a vehicle for traveling on water","a small vessel for traveling on water"]}', NULL, 'by boat / in the same boat; by boat / in the same boat (同命運)', '[{"en":"We crossed the lake by boat.","zh-TW":"我們乘船穿過了湖。"},{"en":"We''re all in the same boat.","zh-TW":"我們都處於同樣的處境。"},{"en":"They crossed the river by boat.","zh-TW":"他們搭船渡河。"},{"en":"We''re all in the same boat.","zh-TW":"我們都處於相同的處境。"}]', NULL, NULL, 1, 712, NULL),
(713, 'body', '/ˈbɒdi/', 'noun', '{"zh-TW":["身體；主體；機構","身體；主體","身體；團體；主體"],"en":["physical structure of a person","an organized group","the physical structure of a person","the physical structure of a person; a group"]}', NULL, 'body language / governing body; body language / body of work', '[{"en":"Body language is important in interviews.","zh-TW":"面試時肢體語言很重要。"},{"en":"The governing body approved the plan.","zh-TW":"管理機構批准了計畫。"},{"en":"Exercise is good for the body.","zh-TW":"運動對身體有好處。"},{"en":"His body language shows confidence.","zh-TW":"他的肢體語言展現了自信。"},{"en":"Exercise is good for the body.","zh-TW":"運動對身體有益。"},{"en":"The governing body approved the plan.","zh-TW":"管理機構批准了這個計畫。"}]', '{"noun":"body","adjective":"bodily"}', NULL, 1, 713, NULL),
(714, 'body composition', '/''bɒdi ˌkɒmpəˈzɪʃən/', 'noun', '{"zh-TW":["身體組成；體格成分"],"en":["the proportion of fat, bone, water, and muscle in the body"]}', NULL, 'measure body composition / improve body composition / body composition analysis', '[{"en":"Changes in body composition, not just body weight, are a better indicator of fitness progress.","zh-TW":"身體組成的變化，而不僅僅是體重，是衡量健身進度的更好指標。"},{"en":"A body composition analysis showed she had increased muscle mass and reduced body fat.","zh-TW":"身體組成分析顯示她增加了肌肉質量並減少了體脂肪。"}]', NULL, NULL, 5, 714, NULL),
(715, 'body language', '/''bɒdi ˌlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["肢體語言；身體語言"],"en":["the movements and postures of the body that express feelings and intentions unconsciously"]}', NULL, 'read body language / positive body language / confident body language', '[{"en":"Maintaining eye contact and open body language projects confidence during interviews.","zh-TW":"在面試中保持眼神接觸和開放的肢體語言能展現自信。"},{"en":"Her body language suggested she was uncomfortable with the proposed solution.","zh-TW":"她的肢體語言表明她對提出的解決方案感到不舒適。"}]', NULL, NULL, 5, 715, NULL),
(716, 'body mass index', '/''bɒdi mæs ˌɪndeks/', 'noun', '{"zh-TW":["身體質量指數；BMI"],"en":["a measure of body fat based on weight and height, used to classify underweight and obesity"]}', NULL, 'calculate body mass index / body mass index chart / healthy body mass index', '[{"en":"A body mass index above thirty is typically classified as obese.","zh-TW":"身體質量指數超過三十通常被歸類為肥胖。"},{"en":"Doctors use body mass index as one indicator of a patient''s overall health.","zh-TW":"醫生使用身體質量指數作為評估患者整體健康狀況的指標之一。"}]', NULL, NULL, 5, 716, NULL),
(717, 'boil', '/''bɔɪl/', 'verb', '{"zh-TW":["煮沸；沸騰"],"en":["to heat a liquid to the point where it boils; to cook food in boiling water"]}', NULL, 'bring to a boil / boil for ten minutes / boil the pasta', '[{"en":"Bring the water to a boil before adding the pasta.","zh-TW":"在加入義大利麵之前，將水煮沸。"},{"en":"Boil the eggs for eight minutes for a hard-boiled result.","zh-TW":"將雞蛋煮八分鐘，得到全熟的水煮蛋。"}]', '{"noun":"boil"}', NULL, 1, 717, NULL),
(718, 'boilerplate clause', '/ˈbɔɪlərpleɪt klɔːz/', 'noun', '{"zh-TW":["標準條款；樣板條款"],"en":["a standard contract clause included as a default in most agreements"]}', NULL, 'include boilerplate clauses / amend a boilerplate clause', '[{"en":"The boilerplate clause on governing law was modified for the jurisdiction.","zh-TW":"管轄法律的標準條款根據司法管轄區進行了修改。"},{"en":"Parties often overlook boilerplate clauses but they can have significant legal impact.","zh-TW":"各方通常忽視標準條款，但它們可能具有重大的法律影響。"}]', NULL, NULL, 5, 718, NULL),
(719, 'bold', '/boʊld/', 'adjective', '{"zh-TW":["大膽的；粗體的"],"en":["willing to take risks","(of text) in a thick dark type"]}', '{"root":{"text":"bold","meaning":"brave (勇敢)"},"logic":"源自古英語 bald（勇敢的）。"}', 'bold move / bold decision / bold font', '[{"en":"That was a bold decision to make.","zh-TW":"那是一個大膽的決定。"},{"en":"Please highlight the key words in bold.","zh-TW":"請用粗體標示關鍵字。"}]', '{"noun":"boldness","adverb":"boldly"}', NULL, 1, 719, NULL),
(720, 'bomb', '/bɒm/', 'noun', '{"zh-TW":["炸彈"],"en":["an explosive weapon"]}', NULL, 'drop a bomb / bomb threat', '[{"en":"The bomb was defused safely.","zh-TW":"炸彈被安全拆除了。"},{"en":"The news dropped like a bomb.","zh-TW":"這消息像炸彈一樣爆開。"}]', '{"verb":"bomb","noun2":"bomber","noun3":"bombing"}', NULL, 1, 720, NULL),
(721, 'bond', '/bɒnd/', 'noun', '{"zh-TW":["債券；紐帶"],"en":["a certificate of debt issued by a government or company","a connection or relationship"]}', '{"root":{"text":"bond","meaning":"bind (綁)"},"logic":"綁定的承諾，即「債券、紐帶」。"}', 'government bond / corporate bond / bond market', '[{"en":"Investors shifted their portfolio toward bonds.","zh-TW":"投資者將投資組合轉向債券。"},{"en":"The company issued bonds to raise capital.","zh-TW":"公司發行債券籌集資金。"}]', NULL, NULL, 1, 721, NULL),
(722, 'bond indenture', '/bɒnd ɪnˈdentʃər/', 'noun', '{"zh-TW":["債券契約"],"en":["a legal contract setting out the terms of a bond between issuer and bondholder"]}', NULL, 'review the bond indenture / bond indenture covenant', '[{"en":"The bond indenture specified a 6% annual coupon payable semi-annually.","zh-TW":"債券契約規定了每半年支付6%的年票息。"},{"en":"Bondholders can enforce their rights through the provisions of the bond indenture.","zh-TW":"債券持有人可以通過債券契約的條款執行其權利。"}]', NULL, NULL, 5, 722, NULL),
(723, 'bond rating', '/bɒnd ˈreɪtɪŋ/', 'noun', '{"zh-TW":["債券評級"],"en":["a score assigned by a rating agency reflecting a bond issuer''s creditworthiness"]}', NULL, 'check bond rating / investment-grade bond rating', '[{"en":"The bond''s rating was downgraded to BB due to weakening earnings.","zh-TW":"由於盈利減弱，債券評級被下調至BB。"},{"en":"A higher bond rating means lower borrowing costs for the issuer.","zh-TW":"較高的債券評級意味著發行人的借貸成本較低。"}]', '{"synonym":"credit rating"}', NULL, 4, 723, NULL),
(724, 'bond spread', '/bɒnd spred/', 'noun', '{"zh-TW":["債券利差"],"en":["the difference in yield between a corporate bond and a government bond of similar maturity"]}', NULL, 'narrow bond spread / widen bond spread / measure bond spread', '[{"en":"A widening bond spread signals that investors see increased credit risk in the issuer.","zh-TW":"債券利差擴大表明投資者認為發行人的信用風險增加了。"},{"en":"Investment-grade bonds typically have a smaller bond spread than high-yield bonds.","zh-TW":"投資級債券的利差通常比高收益債券小。"}]', NULL, NULL, 4, 724, NULL),
(725, 'bond yield', '/bɒnd jiːld/', 'noun', '{"zh-TW":["債券收益率"],"en":["the return an investor receives from a bond expressed as a percentage"]}', NULL, 'rising bond yield / bond yield calculation / compare bond yields', '[{"en":"A rising bond yield makes bonds more attractive to investors.","zh-TW":"上升的債券收益率使債券對投資者更具吸引力。"},{"en":"The government bond yield fell to a record low during the crisis.","zh-TW":"危機期間，政府債券收益率降至歷史最低點。"}]', NULL, NULL, 4, 725, NULL),
(726, 'bonded warehouse', '/''bɒndɪd ˌweərhaʊs/', 'noun', '{"zh-TW":["保稅倉庫；保稅倉"],"en":["a secure storage facility where imported goods are kept before customs duties have been paid"]}', NULL, 'store in a bonded warehouse / bonded warehouse facility / use a bonded warehouse', '[{"en":"Importers can store goods in a bonded warehouse to defer paying customs duties.","zh-TW":"進口商可以將貨物存放在保稅倉庫，以推遲繳納關稅。"},{"en":"The bonded warehouse allowed the company to delay duty payments until goods were sold.","zh-TW":"保稅倉庫使該公司能夠推遲繳納關稅，直到貨物售出。"}]', NULL, NULL, 5, 726, NULL),
(727, 'bone', '/boʊn/', 'noun', '{"zh-TW":["骨頭"],"en":["the hard parts inside the body","the hard parts inside the body that form the skeleton"]}', NULL, 'broken bone / bone dry; bone structure / to the bone', '[{"en":"She broke a bone in her foot.","zh-TW":"她腳上的一根骨頭斷了。"},{"en":"The dog buried the bone.","zh-TW":"狗把骨頭埋了起來。"},{"en":"She broke a bone in her leg.","zh-TW":"她腿骨骨折了。"},{"en":"The cold wind cut to the bone.","zh-TW":"寒風刺骨。"}]', '{"adjective":"bony"}', NULL, 1, 727, NULL),
(728, 'bonus', '/ˈboʊnəs/', 'noun', '{"zh-TW":["獎金；紅利"],"en":["additional payment given to an employee for good performance"]}', NULL, 'performance bonus / annual bonus / sign-on bonus / bonus scheme', '[{"en":"All employees received a year-end bonus this December.","zh-TW":"所有員工今年十二月都收到了年終獎金。"},{"en":"The sales team earned a bonus for exceeding targets.","zh-TW":"銷售團隊因超越目標而獲得獎金。"}]', '{"plural":"bonuses"}', NULL, 2, 728, 829),
(729, 'bonus scheme', '/ˈboʊnəs skiːm/', 'noun', '{"zh-TW":["獎金方案"],"en":["a structured program defining how and when bonuses are earned and paid"]}', NULL, 'implement a bonus scheme / bonus scheme criteria', '[{"en":"The annual bonus scheme rewards employees who exceed their targets.","zh-TW":"年度獎金方案獎勵超過目標的員工。"},{"en":"A transparent bonus scheme improves staff motivation and fairness.","zh-TW":"透明的獎金方案改善了員工積極性和公平性。"}]', '{"synonym":"bonus plan","synonym2":"incentive scheme"}', NULL, 4, 729, NULL),
(730, 'bonus structure', '/ˈboʊnəs ˈstrʌktʃər/', 'noun', '{"zh-TW":["獎金結構"],"en":["the system determining how bonuses are calculated and awarded"]}', NULL, 'design a bonus structure / performance-based bonus structure', '[{"en":"The bonus structure rewards top performers with up to 30% extra pay.","zh-TW":"獎金結構為頂尖表現者提供最高30%的額外薪酬。"},{"en":"The new bonus structure aligns employee incentives with company goals.","zh-TW":"新的獎金結構使員工激勵與公司目標保持一致。"}]', NULL, NULL, 5, 730, NULL),
(731, 'book', '/bʊk/', 'verb', '{"zh-TW":["【主要意義-名詞】書；書籍","【次要意義-動詞】預訂（座位/房間）；登記","【次要意義-動詞（法律/警察用語）】逮捕登記；記錄違規"],"en":["[primary - noun] a set of printed pages bound together","[secondary - verb] to reserve a seat, room, or service in advance","[secondary - verb] to officially record an arrest or charge against someone"]}', NULL, 'book a table / book a flight / fully booked / book someone for speeding', '[{"en":"All seats for the conference have been booked in advance.","zh-TW":"會議的所有座位都已提前預訂。"},{"en":"The hotel is fully booked during the trade show period.","zh-TW":"貿易展期間飯店已全部訂滿。"},{"en":"The officer booked him for driving without a valid license.","zh-TW":"警察以無有效駕照駕車的罪名將他逮捕登記。"}]', '{"noun":"booking, bookkeeper, bookkeeping"}', '動詞 book = 「預訂」是 TOEIC 最常考用法，book a room/flight/table 是必考句型；police book someone（逮捕登記）則較少見，但出現在新聞類文章中。', 1, 731, NULL),
(732, 'book value', '/bʊk ˈvæljuː/', 'noun', '{"zh-TW":["帳面價值"],"en":["the value of an asset as recorded in the financial statements"]}', NULL, 'book value per share / price-to-book ratio / carry at book value', '[{"en":"The stock was trading below its book value, suggesting undervaluation.","zh-TW":"股票以低於帳面價值的價格交易，表明被低估。"},{"en":"Goodwill is often carried on the balance sheet above its book value.","zh-TW":"商譽通常在資產負債表上以高於帳面價值的價格記錄。"}]', NULL, NULL, 4, 732, NULL),
(733, 'book-to-market ratio', '/bʊk tə ˈmɑːrkɪt ˈreɪʃɪəʊ/', 'noun', '{"zh-TW":["帳面市值比"],"en":["the ratio of a company''s book value to its market capitalization"]}', NULL, 'high book-to-market ratio / low book-to-market ratio / use book-to-market ratio', '[{"en":"A high book-to-market ratio can indicate an undervalued stock according to value investing principles.","zh-TW":"根據價值投資原則，高帳面市值比可能表明一支股票被低估。"},{"en":"The Fama-French model uses the book-to-market ratio as a factor to explain stock returns.","zh-TW":"法瑪-法蘭奇模型使用帳面市值比作為解釋股票回報的因子。"}]', NULL, NULL, 5, 733, NULL),
(734, 'booking', '/ˈbʊkɪŋ/', 'noun', '{"zh-TW":["預訂"],"en":["a reservation for accommodation or travel"]}', NULL, 'online booking / advance booking', '[{"en":"Make your booking at least two weeks in advance.","zh-TW":"請至少提前兩週預訂。"},{"en":"The booking was confirmed by email.","zh-TW":"預訂已通過電子郵件確認。"}]', '{"verb":"book","adjective":"booked"}', NULL, 3, 734, NULL),
(735, 'bookkeeping', '/ˈbʊkˌkiːpɪŋ/', 'noun', '{"zh-TW":["簿記；記帳"],"en":["recording financial transactions in a systematic and orderly manner"]}', NULL, 'double-entry bookkeeping / bookkeeping software / outsource bookkeeping', '[{"en":"Accurate bookkeeping is essential for tax compliance.","zh-TW":"準確的簿記對稅務合規至關重要。"},{"en":"She handles all bookkeeping for the small business.","zh-TW":"她處理小企業的所有簿記工作。"}]', '{"noun":"bookkeeper","verb":"keep books"}', NULL, 4, 735, NULL),
(736, 'boost', '/buːst/', 'verb', '{"zh-TW":["提升；促進"],"en":["to increase or improve something"]}', '{"root":{"text":"boost","meaning":"push up (推高)"},"logic":"推高，即「提升」。"}', 'boost sales/productivity/morale', '[{"en":"The promotion helped boost sales by 25%.","zh-TW":"促銷活動幫助銷售增長了25%。"},{"en":"Team-building events can boost employee morale.","zh-TW":"團建活動能提升員工士氣。"}]', NULL, NULL, 2, 736, NULL),
(737, 'border', '/ˈbɔːrdər/', 'noun', '{"zh-TW":["邊界；國界"],"en":["the line that separates two countries"]}', NULL, 'cross the border / border control', '[{"en":"They crossed the border at night.","zh-TW":"他們夜間越過了邊境。"},{"en":"The town is on the border of France.","zh-TW":"這個鎮在法國的邊境上。"}]', NULL, NULL, 2, 737, NULL),
(738, 'border control', '/ˈbɔːrdər kənˈtrəʊl/', 'noun', '{"zh-TW":["邊境管制"],"en":["the regulation of people crossing a country''s borders"]}', NULL, 'pass border control / strict border control', '[{"en":"All travelers must pass through border control upon arrival.","zh-TW":"所有旅客抵達時必須通過邊境管制。"},{"en":"Border control officers check passports and visas.","zh-TW":"邊境管制人員檢查護照和簽證。"}]', NULL, NULL, 5, 738, NULL),
(739, 'border crossing', '/''bɔːrdər ˈkrɒsɪŋ/', 'noun', '{"zh-TW":["邊境過境點；入境口岸"],"en":["a place where people and vehicles cross from one country or territory to another"]}', NULL, 'busy border crossing / border crossing procedure / border crossing checkpoint', '[{"en":"The border crossing was crowded with travelers during the holiday season.","zh-TW":"假日期間，邊境過境點擠滿了旅客。"},{"en":"We waited two hours at the border crossing before our passports were stamped.","zh-TW":"我們在邊境過境點等了兩個小時，才蓋上護照印章。"}]', NULL, NULL, 5, 739, NULL),
(740, 'born', '/bɔːrn/', 'adjective', '{"zh-TW":["出生的；天生的"],"en":["brought into life","brought into existence; having a natural ability"]}', NULL, 'born in / born leader; be born / born and raised', '[{"en":"She was born in 1990.","zh-TW":"她1990年出生。"},{"en":"He''s a born leader.","zh-TW":"他是一個天生的領導者。"},{"en":"She was born in 1990.","zh-TW":"她生於1990年。"},{"en":"He''s a born leader.","zh-TW":"他是天生的領導者。"}]', '{"noun":"birth"}', NULL, 1, 740, NULL),
(741, 'borrow', '/ˈbɒrəʊ/', 'verb', '{"zh-TW":["借入"],"en":["to take and use something belonging to someone else with the intention of returning it"]}', '{"root":{"text":"borrow","meaning":"pledge/surety (抵押)"},"logic":"以抵押方式取得，即「借入」。"}', 'borrow money/funds / borrow from', '[{"en":"The company borrowed $5 million to fund expansion.","zh-TW":"公司借入500萬美元資助擴張。"},{"en":"Interest rates affect how much businesses borrow.","zh-TW":"利率影響企業的借款金額。"}]', '{"noun":"borrower"}', NULL, 2, 741, NULL),
(742, 'boss', '/bɒs/', 'noun', '{"zh-TW":["老闆；上司","老闆；指揮"],"en":["a person who is in charge","a person in charge of others","the person in charge; to give orders"]}', NULL, 'the boss / report to the boss; like a boss / boss around; boss sb around', '[{"en":"My boss approved the budget.","zh-TW":"我的老闆批准了預算。"},{"en":"She is a great boss to work for.","zh-TW":"她是一個很好的上司。"},{"en":"My boss gave me a raise.","zh-TW":"我老闆給我加薪了。"},{"en":"Stop bossing me around.","zh-TW":"別再對我指手畫腳了。"},{"en":"My boss approved my vacation request.","zh-TW":"我的老闆批准了我的休假申請。"},{"en":"Stop bossing me around.","zh-TW":"別再對我發號施令。"}]', '{"noun":"boss","adjective":"bossy"}', NULL, 1, 742, NULL),
(743, 'both', '/boʊθ/', 'determiner', '{"zh-TW":["兩者都"],"en":["the two; each of two things","used to refer to two things or people together"]}', NULL, 'both... and / both sides; both...and... / both of', '[{"en":"Both answers are correct.","zh-TW":"兩個答案都正確。"},{"en":"She speaks both English and French.","zh-TW":"她英語和法語都會說。"},{"en":"Both options are acceptable.","zh-TW":"兩個選項都可以接受。"},{"en":"Both of them passed the exam.","zh-TW":"他們兩個都通過了考試。"}]', NULL, NULL, 1, 743, NULL),
(744, 'bother', '/ˈbɒðər/', 'verb', '{"zh-TW":["打擾；煩惱"],"en":["to annoy or trouble someone","to cause worry or annoyance","to make the effort to do something"]}', '{"root":{"text":"bother","meaning":"confuse/annoy (困擾)"},"logic":"指使人感到困擾或不安。"}', 'don''t bother / sorry to bother; don''t bother / sorry to bother you / it bothers me', '[{"en":"Sorry to bother you.","zh-TW":"抱歉打擾你了。"},{"en":"Don''t bother waiting for me.","zh-TW":"不用費心等我了。"},{"en":"Sorry to bother you, but I need help.","zh-TW":"抱歉打擾你，但我需要幫忙。"},{"en":"The noise doesn''t bother me.","zh-TW":"噪音不會困擾我。"}]', '{"noun":"bother","adjective":"bothersome"}', NULL, 2, 744, NULL),
(745, 'bottleneck', '/ˈbɒtəlnɛk/', 'noun', '{"zh-TW":["瓶頸"],"en":["a point of congestion that slows progress"]}', NULL, 'production bottleneck / identify bottlenecks', '[{"en":"Shipping is the main bottleneck.","zh-TW":"運輸是主要瓶頸。"},{"en":"We identified several bottlenecks in the process.","zh-TW":"我們找出了流程中的幾個瓶頸。"}]', '{"noun":"bottleneck"}', NULL, 4, 745, NULL),
(746, 'bottom', '/ˈbɒtəm/', 'noun', '{"zh-TW":["底部；最低處","底部；最低的"],"en":["the lowest part of something","the lowest part; at the lowest position"]}', NULL, 'at the bottom / from top to bottom; at the bottom of / bottom line', '[{"en":"Sign at the bottom of the page.","zh-TW":"在頁面底部簽名。"},{"en":"He started from the bottom.","zh-TW":"他從底層開始做起。"},{"en":"The bottom line is we need more funding.","zh-TW":"重點是我們需要更多資金。"}]', NULL, NULL, 2, 746, NULL),
(747, 'bottom line', '/ˈbɒtəm laɪn/', 'noun', '{"zh-TW":["底線；淨利潤；核心要點"],"en":["a company''s net income; the final or most essential point"]}', NULL, 'improve the bottom line / impact the bottom line / bottom-line results', '[{"en":"The cost cuts significantly improved the company''s bottom line.","zh-TW":"成本削減顯著改善了公司的淨利潤。"},{"en":"The bottom line is that we need to increase revenue by 20%.","zh-TW":"核心要點是我們需要將收入增加20%。"}]', NULL, NULL, 4, 747, NULL),
(748, 'bottom-up', '/ˈbɒtəm ʌp/', 'adjective', '{"zh-TW":["自下而上的"],"en":["proceeding from the most basic units to a larger structure"]}', NULL, 'bottom-up approach / bottom-up design / bottom-up analysis', '[{"en":"A bottom-up approach to budgeting involves input from all levels.","zh-TW":"自下而上的預算方法涉及各層級的意見。"},{"en":"The reform was driven by bottom-up pressure from community organizations.","zh-TW":"改革由社區組織的自下而上壓力推動。"}]', '{"antonym":"top-down"}', NULL, 3, 748, NULL),
(749, 'bounce back', '/baʊns bæk/', 'verb', '{"zh-TW":["反彈；恢復"],"en":["to recover quickly after a setback or decline"]}', NULL, 'bounce back from losses / bounce back quickly', '[{"en":"The company bounced back strongly in Q2 after Q1 losses.","zh-TW":"公司在第一季虧損後，第二季強勁反彈。"},{"en":"Markets bounced back within weeks after the initial shock.","zh-TW":"市場在最初衝擊後的數週內反彈了。"}]', '{"noun":"bounce-back","adjective":"bounced back"}', NULL, 4, 749, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(750, 'boundary', '/ˈbaʊndri/', 'noun', '{"zh-TW":["邊界；界線","邊界；界限"],"en":["a line that marks the limit of an area","a line marking the limits of an area"]}', '{"root":{"text":"bound","meaning":"limit (限制)"},"suffix":{"text":"-ary","meaning":"relating to (有關的)"},"logic":"與限制有關的，即「邊界」。"}', 'cross boundaries / set boundaries; set boundaries / cross a boundary / boundary line', '[{"en":"The project crosses departmental boundaries.","zh-TW":"該專案跨越了部門界線。"},{"en":"It''s important to set professional boundaries.","zh-TW":"設定專業界線很重要。"},{"en":"The river forms the boundary between the two countries.","zh-TW":"這條河構成兩國之間的邊界。"},{"en":"It''s important to set personal boundaries.","zh-TW":"設立個人界限很重要。"}]', '{"adjective":"bounded","verb":"bound"}', NULL, 3, 750, NULL),
(751, 'bounded rationality', '/ˈbaʊndɪd ˌræʃəˈnælɪti/', 'noun', '{"zh-TW":["有限理性"],"en":["the idea that decision-making is limited by available information, cognitive capacity, and time"]}', NULL, 'bounded rationality model / cognitive bounded rationality / bounded rationality in economics', '[{"en":"Herbert Simon''s bounded rationality concept transformed how economists model decision-making.","zh-TW":"赫伯特·賽門的有限理性概念改變了經濟學家對決策建模的方式。"},{"en":"Bounded rationality explains why people use heuristics rather than complex calculations.","zh-TW":"有限理性解釋了為什麼人們使用啟發法而不是複雜計算。"}]', NULL, NULL, 5, 751, NULL),
(752, 'boutique', '/buːˈtiːk/', 'noun', '{"zh-TW":["精品店；小型專賣店"],"en":["a small shop selling fashionable items"]}', '{"root":{"text":"boutique","meaning":"small shop (小店)"},"logic":"源自法語，指販售精品的小型商店。"}', 'boutique hotel / fashion boutique', '[{"en":"She opened a boutique selling handmade jewelry.","zh-TW":"她開了一家賣手工飾品的精品店。"},{"en":"The boutique hotel offers personalized service.","zh-TW":"這家精品旅館提供個人化服務。"}]', NULL, NULL, 3, 752, NULL),
(753, 'bowl', '/boʊl/', 'noun', '{"zh-TW":["碗"],"en":["a round deep dish"]}', NULL, 'bowl of soup / mixing bowl', '[{"en":"Have a bowl of soup.","zh-TW":"喝一碗湯吧。"},{"en":"Put the salad in a large bowl.","zh-TW":"把沙拉放在一個大碗裡。"}]', NULL, NULL, 1, 753, NULL),
(754, 'box', '/bɒks/', 'noun', '{"zh-TW":["箱子；盒子"],"en":["a container with flat sides"]}', NULL, 'cardboard box / think outside the box', '[{"en":"She opened the box carefully.","zh-TW":"她小心地打開了盒子。"},{"en":"We need to think outside the box.","zh-TW":"我們需要跳出框架思考。"}]', NULL, NULL, 1, 754, NULL),
(755, 'boycott', '/ˈbɔɪkɒt/', 'noun', '{"zh-TW":["抵制；聯合抵制"],"en":["a refusal to buy goods or participate in activities as a form of protest"]}', NULL, 'organize a boycott / consumer boycott / call for a boycott', '[{"en":"A consumer boycott of the company''s products hurt its sales significantly.","zh-TW":"消費者對該公司產品的抵制顯著損害了其銷售額。"},{"en":"The boycott was lifted after the company agreed to improve labor practices.","zh-TW":"在公司同意改善勞工做法後，抵制被解除。"}]', '{"verb":"boycott"}', NULL, 3, 755, NULL),
(756, 'brain', '/breɪn/', 'noun', '{"zh-TW":["大腦；腦力","大腦；頭腦"],"en":["the organ of thought","intelligence","the organ inside the head that controls the body"]}', NULL, 'brainstorm / brain drain; brain storm / brain power', '[{"en":"Let''s brainstorm some ideas.","zh-TW":"讓我們腦力激盪一些點子。"},{"en":"Brain drain is a serious issue.","zh-TW":"人才外流是嚴重的問題。"},{"en":"The brain controls all body functions.","zh-TW":"大腦控制所有的身體功能。"},{"en":"Use your brain!","zh-TW":"動動腦筋！"}]', '{"noun":"brain","adjective":"brainy","verb":"brainstorm"}', NULL, 2, 756, NULL),
(757, 'brainstorm', '/ˈbreɪnstɔːrm/', 'verb', '{"zh-TW":["腦力激盪；集思廣益"],"en":["to suggest many ideas quickly in a group"]}', NULL, 'brainstorm ideas / brainstorming session', '[{"en":"The team brainstormed solutions to the supply chain problem.","zh-TW":"團隊就供應鏈問題進行了腦力激盪。"},{"en":"The brainstorming session generated over 30 new ideas.","zh-TW":"腦力激盪會議產生了超過30個新想法。"}]', '{"noun":"brainstorm","noun2":"brainstorming"}', NULL, 4, 757, NULL),
(758, 'brainstorming session', '/ˈbreɪnstɔːmɪŋ ˈsɛʃən/', 'noun', '{"zh-TW":["腦力激盪會議"],"en":["a meeting held to generate creative ideas"]}', NULL, 'hold a brainstorming session / productive brainstorming session', '[{"en":"The team held a brainstorming session to develop new product ideas.","zh-TW":"團隊舉行了腦力激盪會議以開發新產品創意。"},{"en":"A good brainstorming session builds team creativity.","zh-TW":"良好的腦力激盪會議能夠增強團隊創造力。"}]', NULL, NULL, 5, 758, NULL),
(759, 'branch', '/brɑːntʃ/', 'noun', '{"zh-TW":["分公司；分支"],"en":["a division of a larger organization","a local office of a company"]}', '{"root":{"text":"branch","meaning":"arm/limb (樹枝/手臂)"},"logic":"從主體延伸出去的，即「分支」。"}', 'branch office / branch manager / open a branch', '[{"en":"The bank has over 200 branches nationwide.","zh-TW":"該銀行在全國有超過200家分行。"},{"en":"We plan to open a new branch in Taipei.","zh-TW":"我們計劃在台北開設新分公司。"}]', NULL, NULL, 2, 759, 77),
(760, 'brand', '/brænd/', 'noun', '{"zh-TW":["品牌","品牌；商標"],"en":["a type of product made by a particular company"]}', '{"root":{"text":"brand","meaning":"burn/mark (燒/標記)"},"logic":"燒印標記以識別，即「品牌」。"}', 'brand awareness / brand image / brand loyalty; brand name / brand loyalty / brand awareness', '[{"en":"Building a strong brand takes years of effort.","zh-TW":"建立強大的品牌需要多年努力。"},{"en":"The new campaign increased brand awareness by 30%.","zh-TW":"新活動將品牌知名度提高了30%。"},{"en":"This brand is known for its high quality.","zh-TW":"這個品牌以高品質聞名。"},{"en":"They are trying to build brand awareness.","zh-TW":"他們正努力建立品牌知名度。"}]', '{"noun":"branding","verb":"brand","adjective":"branded"}', NULL, 2, 760, NULL),
(761, 'brand ambassador', '/brænd æmˈbæsədər/', 'noun', '{"zh-TW":["品牌大使"],"en":["a person employed to promote and represent a brand publicly"]}', NULL, 'appoint a brand ambassador / brand ambassador deal / become a brand ambassador', '[{"en":"The athlete became a brand ambassador for the sportswear company.","zh-TW":"這位運動員成為了運動服裝公司的品牌大使。"},{"en":"Brand ambassadors help humanize the company''s image.","zh-TW":"品牌大使幫助使公司形象更加人性化。"}]', '{"plural":"brand ambassadors"}', NULL, 5, 761, NULL),
(762, 'brand awareness', '/brænd əˈweənəs/', 'noun', '{"zh-TW":["品牌知名度"],"en":["the extent to which consumers recognize a brand"]}', NULL, 'build brand awareness / increase brand awareness / measure brand awareness', '[{"en":"The campaign significantly increased brand awareness among millennials.","zh-TW":"該活動顯著提高了千禧世代對品牌的認知。"},{"en":"Social media is an effective tool for building brand awareness.","zh-TW":"社群媒體是建立品牌知名度的有效工具。"}]', '{"adjective":"brand-aware"}', NULL, 5, 762, NULL),
(763, 'brand equity', '/brænd ˈekwɪti/', 'noun', '{"zh-TW":["品牌資產；品牌價值"],"en":["the commercial value of a brand beyond its physical assets"]}', NULL, 'build brand equity / measure brand equity / strong brand equity', '[{"en":"Strong brand equity allows companies to charge premium prices.","zh-TW":"強大的品牌資產讓公司能夠收取溢價。"},{"en":"Consistent quality builds brand equity over time.","zh-TW":"持續的品質隨時間建立品牌資產。"}]', NULL, NULL, 4, 763, NULL),
(764, 'brand guidelines', '/brænd ˈɡaɪdlaɪnz/', 'noun', '{"zh-TW":["品牌指南"],"en":["a set of rules defining how a brand should be presented visually and verbally"]}', NULL, 'follow brand guidelines / create brand guidelines / brand guidelines document', '[{"en":"All marketing materials must adhere to the brand guidelines.","zh-TW":"所有行銷材料必須遵守品牌指南。"},{"en":"The brand guidelines specify approved fonts, colors, and logo usage.","zh-TW":"品牌指南規定了批准的字體、顏色和標誌使用方式。"}]', NULL, NULL, 5, 764, NULL),
(765, 'brand loyalty', '/brænd ˈlɔɪəlti/', 'noun', '{"zh-TW":["品牌忠誠度"],"en":["a consumer''s consistent preference for one brand over others"]}', NULL, 'build brand loyalty / brand loyalty program / strong brand loyalty', '[{"en":"Excellent customer service is key to building brand loyalty.","zh-TW":"出色的客戶服務是建立品牌忠誠度的關鍵。"},{"en":"Brand loyalty declined after the quality scandal.","zh-TW":"品質醜聞後品牌忠誠度下降。"}]', '{"adjective":"brand-loyal"}', NULL, 5, 765, NULL),
(766, 'brand voice', '/''brænd vɔɪs/', 'noun', '{"zh-TW":["品牌聲音；品牌語氣"],"en":["the unique personality and style of communication that a brand uses across all channels"]}', NULL, 'define brand voice / consistent brand voice / develop brand voice', '[{"en":"A consistent brand voice builds recognition and trust with customers.","zh-TW":"一致的品牌聲音建立了顧客的認知度和信任感。"},{"en":"The marketing team developed a friendly and approachable brand voice for the new product.","zh-TW":"行銷團隊為新產品開發了友好且平易近人的品牌聲音。"}]', NULL, NULL, 4, 766, NULL),
(767, 'branding', '/ˈbrændɪŋ/', 'noun', '{"zh-TW":["品牌塑造；品牌化"],"en":["the process of creating a distinctive identity for a company or product"]}', NULL, 'corporate branding / product branding / employer branding / personal branding', '[{"en":"Strong branding distinguishes the company from competitors.","zh-TW":"強大的品牌塑造使公司與競爭對手區別開來。"},{"en":"The rebranding effort modernized the company''s image.","zh-TW":"重新品牌化工作使公司形象現代化。"}]', '{"verb":"brand","noun":"brand"}', NULL, 3, 767, NULL),
(768, 'brave', '/breɪv/', 'adjective', '{"zh-TW":["勇敢的"],"en":["ready to face danger"]}', NULL, 'brave enough / brave face', '[{"en":"She was brave to speak up.","zh-TW":"她勇敢地站出來發言。"},{"en":"The brave soldier saved his team.","zh-TW":"勇敢的士兵拯救了他的隊伍。"}]', '{"noun":"bravery","adverb":"bravely"}', NULL, 2, 768, NULL),
(769, 'breach', '/briːtʃ/', 'noun', '{"zh-TW":["違反；破壞"],"en":["a failure to observe a law, agreement, or code of conduct"]}', '{"root":{"text":"breach","meaning":"break (打破)"},"logic":"打破規則，即「違反」。"}', 'breach of contract / security breach / data breach', '[{"en":"The lawsuit alleges a breach of contract.","zh-TW":"訴訟指控違反合約。"},{"en":"A data breach exposed customer information.","zh-TW":"資料外洩暴露了客戶資訊。"}]', NULL, NULL, 2, 769, NULL),
(770, 'breach of contract', '/briːtʃ əv ˈkɒntrækt/', 'noun', '{"zh-TW":["違約；違反合同"],"en":["the failure to fulfill a legal obligation under a contract"]}', NULL, 'claim breach of contract / breach of contract lawsuit / remedy breach of contract', '[{"en":"The supplier''s failure to deliver on time constituted breach of contract.","zh-TW":"供應商未能按時交付構成違約。"},{"en":"The company sued for breach of contract and was awarded damages.","zh-TW":"公司以違約為由提起訴訟並獲得損害賠償。"}]', NULL, NULL, 5, 770, NULL),
(771, 'breach of duty', '/briːtʃ əv ˈdjuːti/', 'noun', '{"zh-TW":["違反職責"],"en":["a failure to meet a legal or professional obligation owed to another person"]}', NULL, 'commit breach of duty / prove breach of duty', '[{"en":"The manager''s actions constituted a clear breach of duty.","zh-TW":"該管理者的行為構成了明顯的違反職責。"},{"en":"Directors can be held liable for breach of duty to shareholders.","zh-TW":"董事可能因違反對股東的職責而承擔責任。"}]', NULL, NULL, 5, 771, NULL),
(772, 'breach of warranty', '/briːtʃ əv ˈwɒrənti/', 'noun', '{"zh-TW":["違反保固；違約保證"],"en":["a failure to fulfill a promise or guarantee made in a contract"]}', NULL, 'file for breach of warranty / breach of warranty claim', '[{"en":"The customer filed a claim for breach of warranty on the defective product.","zh-TW":"客戶就有缺陷的產品提出了違反保固索賠。"},{"en":"Breach of warranty may entitle the buyer to a refund or replacement.","zh-TW":"違反保固可能使買方有權獲得退款或更換。"}]', NULL, NULL, 5, 772, NULL),
(773, 'bread', '/brɛd/', 'noun', '{"zh-TW":["麵包"],"en":["food made from flour and water"]}', NULL, 'slice of bread / bread and butter', '[{"en":"I''d like some bread, please.","zh-TW":"請給我一些麵包。"},{"en":"Teaching is her bread and butter.","zh-TW":"教書是她的生計。"}]', NULL, NULL, 2, 773, NULL),
(774, 'break', '/breɪk/', 'noun', '{"zh-TW":["休息；打破","打破；休息"],"en":["a pause in work","to separate into pieces"]}', NULL, 'take a break / break down; break down / take a break', '[{"en":"Let''s take a 15-minute break.","zh-TW":"我們休息15分鐘吧。"},{"en":"The machine broke down yesterday.","zh-TW":"機器昨天故障了。"},{"en":"Be careful not to break it.","zh-TW":"小心別打破了。"},{"en":"Let''s take a short break.","zh-TW":"讓我們休息一下。"}]', '{"verb":"break","noun":"break","noun2":"breakdown","adjective":"breakable"}', NULL, 2, 774, NULL),
(775, 'break clause', '/breɪk klɔːz/', 'noun', '{"zh-TW":["解除條款；終止選項"],"en":["a provision in a lease allowing either party to terminate before the end of the term"]}', NULL, 'exercise a break clause / break clause option', '[{"en":"The tenant exercised the break clause after two years.","zh-TW":"租戶在兩年後行使了解除條款。"},{"en":"A break clause adds flexibility for tenants in long lease agreements.","zh-TW":"解除條款在長期租約協議中為租戶增加了靈活性。"}]', NULL, NULL, 4, 775, NULL),
(776, 'break even', '/breɪk ˈiːvən/', 'verb', '{"zh-TW":["達到損益兩平；回本"],"en":["to reach the point where revenues equal costs"]}', NULL, 'expected to break even / break even by year 2', '[{"en":"The company is expected to break even by the end of Q3.","zh-TW":"公司預計到第三季末達到損益兩平。"},{"en":"It took five years for the new branch to break even.","zh-TW":"新分支機構花了五年時間才回本。"}]', '{"noun":"break-even","adjective":"break-even"}', NULL, 4, 776, NULL),
(777, 'break-even', '/breɪk ˈiːvən/', 'noun', '{"zh-TW":["損益兩平；盈虧平衡點"],"en":["the point at which revenues equal costs"]}', NULL, 'reach break-even / break-even point', '[{"en":"The company expects to reach break-even by the third quarter.","zh-TW":"公司預計在第三季度達到損益兩平。"},{"en":"Calculating the break-even point helps set realistic sales targets.","zh-TW":"計算盈虧平衡點有助於設定切實可行的銷售目標。"}]', '{"adjective":"break-even"}', NULL, 4, 777, NULL),
(778, 'break-even analysis', '/ˌbreɪk ˈiːvən əˈnæləsɪs/', 'noun', '{"zh-TW":["損益平衡分析"],"en":["a financial calculation to determine the point at which revenues equal costs"]}', NULL, 'perform break-even analysis / break-even analysis results', '[{"en":"Break-even analysis showed the product would be profitable after 6 months.","zh-TW":"損益平衡分析顯示該產品在6個月後將盈利。"},{"en":"Break-even analysis is essential before launching any new product.","zh-TW":"在推出任何新產品之前，損益平衡分析是必不可少的。"}]', NULL, NULL, 5, 778, NULL),
(779, 'break-even point', '/''breɪk ˌiːvən pɔɪnt/', 'noun', '{"zh-TW":["損益平衡點；盈虧平衡點"],"en":["the point at which total revenues equal total costs, resulting in neither profit nor loss"]}', NULL, 'reach the break-even point / calculate the break-even point / below the break-even point', '[{"en":"The startup expects to reach its break-even point within eighteen months.","zh-TW":"這家初創公司預計在十八個月內達到損益平衡點。"},{"en":"Knowing your break-even point is essential for setting appropriate pricing strategies.","zh-TW":"了解你的損益平衡點對於制定適當的定價策略至關重要。"}]', '{"verb":"break even","noun":"break-even"}', NULL, 5, 779, NULL),
(780, 'breakeven', '/ˈbreɪkˌiːvən/', 'noun', '{"zh-TW":["損益平衡點"],"en":["the point at which revenues equal costs with neither profit nor loss"]}', NULL, 'breakeven point / reach breakeven / breakeven analysis', '[{"en":"The startup reached breakeven after 18 months.","zh-TW":"新創公司在18個月後達到了損益平衡點。"},{"en":"Breakeven analysis helps determine minimum sales needed.","zh-TW":"損益平衡分析有助於確定所需的最低銷售量。"}]', '{"verb":"break even"}', NULL, 3, 780, NULL),
(781, 'breakeven point', '/ˈbreɪkˌiːvən pɔɪnt/', 'noun', '{"zh-TW":["損益兩平點；保本點"],"en":["the level of sales at which total revenues equal total costs, resulting in zero profit or loss"]}', NULL, 'calculate the breakeven point / reach the breakeven point', '[{"en":"The breakeven point was reached in the 8th month of operations.","zh-TW":"在運營的第8個月達到了損益兩平點。"},{"en":"Knowing the breakeven point helps set realistic sales targets.","zh-TW":"了解損益兩平點有助於設定現實的銷售目標。"}]', NULL, NULL, 5, 781, NULL),
(782, 'breakout strategy', '/ˈbreɪkaʊt ˈstrætədʒi/', 'noun', '{"zh-TW":["突破策略"],"en":["a plan to move beyond current market position into a new area of growth"]}', NULL, 'develop a breakout strategy / execute the breakout strategy', '[{"en":"The breakout strategy targeted three new international markets.","zh-TW":"突破策略針對了三個新的國際市場。"},{"en":"A bold breakout strategy reversed five years of declining sales.","zh-TW":"大膽的突破策略扭轉了五年的銷售下滑。"}]', NULL, NULL, 5, 782, NULL),
(783, 'breakthrough', '/ˈbreɪkθruː/', 'noun', '{"zh-TW":["突破"],"en":["a sudden important development or discovery"]}', '{"root":{"text":"break","meaning":"break (打破)"},"suffix":{"text":"through","meaning":"through (穿過)"},"logic":"打破穿過障礙，即「突破」。"}', 'major breakthrough / technological breakthrough', '[{"en":"The research team achieved a major breakthrough.","zh-TW":"研究團隊取得了重大突破。"},{"en":"This technology represents a breakthrough in AI.","zh-TW":"這項技術代表了人工智慧的突破。"}]', NULL, NULL, 4, 783, NULL),
(784, 'breath', '/brɛθ/', 'noun', '{"zh-TW":["呼吸；氣息"],"en":["the air that goes in and out of lungs"]}', NULL, 'take a breath / out of breath', '[{"en":"Take a deep breath.","zh-TW":"深呼吸。"},{"en":"She was out of breath from running.","zh-TW":"她跑得上氣不接下氣。"}]', '{"verb":"breathe","adjective":"breathless"}', NULL, 2, 784, NULL),
(785, 'breeze', '/briːz/', 'noun', '{"zh-TW":["微風"],"en":["a gentle wind"]}', '{"root":{"text":"breeze","meaning":"light wind (輕風)"},"logic":"指輕柔的風。"}', 'a gentle breeze / sea breeze', '[{"en":"A cool breeze blew in from the ocean.","zh-TW":"一陣涼爽的海風吹來。"},{"en":"The curtains moved gently in the breeze.","zh-TW":"窗簾在微風中輕輕飄動。"}]', '{"adjective":"breezy"}', NULL, 2, 785, NULL),
(786, 'brevity', '/''brevɪti/', 'noun', '{"zh-TW":["簡潔；簡短"],"en":["the quality of using few words to say something; conciseness"]}', NULL, 'write with brevity / brevity is key / appreciate brevity', '[{"en":"In business writing, brevity is valued because readers have limited time.","zh-TW":"在商業寫作中，簡潔受到重視，因為讀者的時間有限。"},{"en":"The keynote speaker was praised for the brevity and impact of his presentation.","zh-TW":"主題演講者因其演講的簡潔和影響力而受到稱讚。"}]', '{"adjective":"brief"}', NULL, 3, 786, NULL),
(787, 'bridge', '/brɪdʒ/', 'noun', '{"zh-TW":["橋；橋梁"],"en":["a structure over a river or road"]}', NULL, 'build a bridge / bridge the gap', '[{"en":"They built a new bridge over the river.","zh-TW":"他們在河上建了一座新橋。"},{"en":"Education bridges the gap.","zh-TW":"教育彌合了差距。"}]', NULL, NULL, 2, 787, NULL),
(788, 'bridge loan', '/brɪdʒ loʊn/', 'noun', '{"zh-TW":["過渡貸款；橋接融資"],"en":["a short-term loan used to bridge a gap until permanent financing is arranged"]}', NULL, 'arrange a bridge loan / bridge loan facility', '[{"en":"The company took a bridge loan to fund the acquisition while awaiting bond issuance.","zh-TW":"公司在等待債券發行期間獲取了過渡貸款以資助收購。"},{"en":"Bridge loans carry higher interest rates than long-term loans.","zh-TW":"過渡貸款的利率比長期貸款高。"}]', NULL, NULL, 4, 788, NULL),
(789, 'brief', '/briːf/', 'adjective', '{"zh-TW":["【主要意義-形容詞】簡短的；短暫的","【次要意義-動詞】簡報；叮囑；向……作摘要說明","【次要意義-名詞】概要；任務說明；（律師的）案件摘要"],"en":["[primary - adjective] short in duration or length","[secondary - verb] to give someone essential information before a task","[secondary - noun] a set of instructions or a summary of key information"]}', '{"root":{"text":"brev","meaning":"short (短)"},"logic":"短的，即「簡短的」。"}', 'brief someone on / be briefed about / mission brief / design brief', '[{"en":"Managers were briefed on the new safety procedures before implementation.","zh-TW":"管理人員在實施前已就新安全程序進行了匯報。"},{"en":"The design team received a detailed brief outlining the client requirements.","zh-TW":"設計團隊收到了一份詳細說明客戶需求的任務說明書。"},{"en":"The consultant was briefed thoroughly before meeting the board.","zh-TW":"顧問在與董事會見面之前已進行了全面的情況說明。"}]', '{"noun":"briefing","adverb":"briefly"}', '動詞 brief = 「向某人匯報/說明情況」，名詞 brief = 「任務說明/概要」，TOEIC 商業會議或專案管理文章的常見用法，考生容易只記住形容詞「簡短的」。', 2, 789, 830),
(790, 'briefing', '/ˈbriːfɪŋ/', 'noun', '{"zh-TW":["簡報；情況說明"],"en":["a meeting where information is given to prepare people"]}', NULL, 'daily briefing / press briefing', '[{"en":"The manager gave a briefing on the quarterly results.","zh-TW":"經理就季度業績進行了簡報。"},{"en":"All staff attended a safety briefing before the site visit.","zh-TW":"所有員工在現場參觀前參加了安全簡報。"}]', '{"verb":"brief","adjective":"briefed"}', NULL, 3, 790, NULL),
(791, 'briefing session', '/''briːfɪŋ ˌseʃən/', 'noun', '{"zh-TW":["情況說明會；簡報會議"],"en":["a meeting in which people are given information or instructions about something"]}', NULL, 'attend a briefing session / hold a briefing session / mandatory briefing session', '[{"en":"All new employees must attend a briefing session on workplace health and safety.","zh-TW":"所有新員工必須參加工作場所健康安全情況說明會。"},{"en":"The project manager held a briefing session to update the team on changes to the scope.","zh-TW":"項目經理召開了情況說明會，向團隊說明範圍的變化。"}]', NULL, NULL, 5, 791, NULL),
(792, 'bright', '/braɪt/', 'adjective', '{"zh-TW":["明亮的；聰明的"],"en":["giving out much light; intelligent"]}', NULL, 'bright future / bright idea', '[{"en":"The sun is very bright today.","zh-TW":"今天太陽很亮。"},{"en":"She has a bright future ahead.","zh-TW":"她前途光明。"}]', '{"noun":"brightness","adverb":"brightly","verb":"brighten"}', NULL, 2, 792, NULL),
(793, 'brilliant', '/ˈbrɪliənt/', 'adjective', '{"zh-TW":["傑出的；明亮的"],"en":["exceptionally clever or talented","very bright"]}', '{"root":{"text":"brill","meaning":"shine (閃耀)"},"suffix":{"text":"-iant","meaning":"being (…的)"},"logic":"閃耀著光芒的，即「傑出的」。"}', 'brilliant idea / brilliant career / brilliant color', '[{"en":"She had a brilliant idea for the project.","zh-TW":"她對這個專案有個絕妙的點子。"},{"en":"He has had a brilliant career in science.","zh-TW":"他在科學領域有卓越的職業生涯。"}]', '{"noun":"brilliance","adverb":"brilliantly"}', NULL, 3, 793, NULL),
(794, 'bring', '/brɪŋ/', 'verb', '{"zh-TW":["帶來；引起"],"en":["to carry to a place","to cause","to carry something to a place"]}', NULL, 'bring about / bring up; bring up / bring about', '[{"en":"Please bring your laptop to the meeting.","zh-TW":"請帶你的筆電來開會。"},{"en":"The merger brought about many changes.","zh-TW":"合併帶來了許多變化。"},{"en":"Bring your umbrella.","zh-TW":"把傘帶上。"},{"en":"What brought about this change?","zh-TW":"是什麼引起了這個改變？"}]', '{"verb":"bring"}', NULL, 2, 794, NULL),
(795, 'bring forward', '/brɪŋ ˈfɔːrwərd/', 'verb', '{"zh-TW":["提前；結轉"],"en":["to move something to an earlier time or to carry a balance to the next period"]}', NULL, 'bring forward a meeting / bring forward a balance', '[{"en":"The project deadline was brought forward by two weeks due to market pressure.","zh-TW":"由於市場壓力，項目截止日期提前了兩週。"},{"en":"The surplus was brought forward to the next financial year.","zh-TW":"盈餘被結轉到下一個財政年度。"}]', NULL, NULL, 5, 795, NULL),
(796, 'broad', '/brɔːd/', 'adjective', '{"zh-TW":["廣泛的；寬闊的","寬闊的；廣泛的"],"en":["having a large distance from side to side","covering a wide range","wide; covering a large area"]}', '{"root":{"text":"broad","meaning":"wide (寬)"},"logic":"寬的，即「廣泛的」。"}', 'broad range / broad experience / broad spectrum; broad range / broad daylight', '[{"en":"The company offers a broad range of services.","zh-TW":"公司提供廣泛的服務。"},{"en":"She has broad experience in international trade.","zh-TW":"她在國際貿易方面有廣泛經驗。"},{"en":"The river is very broad here.","zh-TW":"河在這裡非常寬。"},{"en":"It happened in broad daylight.","zh-TW":"這發生在光天化日之下。"}]', '{"adverb":"broadly","verb":"broaden"}', NULL, 2, 796, NULL),
(797, 'broadcast', '/ˈbrɔːdkæst/', 'verb', '{"zh-TW":["廣播；播放"],"en":["to send out programs by radio or TV"]}', NULL, 'live broadcast / broadcast news', '[{"en":"The game will be broadcast live.","zh-TW":"比賽將現場直播。"},{"en":"The news is broadcast at six.","zh-TW":"新聞在六點播出。"}]', '{"noun":"broadcast","noun2":"broadcaster"}', NULL, 3, 797, 517),
(798, 'broaden', '/ˈbrɔːdən/', 'verb', '{"zh-TW":["擴大；拓寬"],"en":["to make something wider or more inclusive in scope"]}', NULL, 'broaden the scope / broaden the customer base', '[{"en":"The company broadened its product range to include health supplements.","zh-TW":"公司擴大了其產品系列以包括健康補充劑。"},{"en":"The partnership broadened the firm''s access to new markets.","zh-TW":"夥伴關係擴大了公司進入新市場的管道。"}]', '{"adjective":"broadened","noun":"broadening"}', NULL, 3, 798, NULL),
(799, 'broadsheet', '/ˈbrɔːdʃiːt/', 'noun', '{"zh-TW":["大版報紙；嚴肅報紙"],"en":["a newspaper printed on large paper with serious content"]}', NULL, 'read a broadsheet / national broadsheet / broadsheet journalism', '[{"en":"Broadsheet newspapers tend to feature in-depth analysis and investigative reporting.","zh-TW":"大版報紙傾向於提供深度分析和調查報導。"},{"en":"The broadsheet published a comprehensive series on economic inequality.","zh-TW":"這份嚴肅報紙發表了一系列關於經濟不平等的深度報導。"}]', NULL, NULL, 4, 799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(800, 'broken', '/ˈbroʊkən/', 'adjective', '{"zh-TW":["破碎的；壞掉的"],"en":["damaged and no longer working"]}', NULL, 'broken heart / broken promise', '[{"en":"The window is broken.","zh-TW":"窗戶破了。"},{"en":"He has a broken heart.","zh-TW":"他傷心透了。"}]', NULL, NULL, 2, 800, NULL),
(801, 'broker', '/ˈbroʊkər/', 'noun', '{"zh-TW":["經紀人；仲介"],"en":["an agent who arranges transactions between buyers and sellers"]}', NULL, 'insurance broker / real estate broker / commodity broker', '[{"en":"The real estate broker negotiated a favorable lease on our behalf.","zh-TW":"房地產經紀人代我們協商了有利的租賃條件。"},{"en":"A broker was hired to arrange the bond issuance.","zh-TW":"聘請了一名經紀人安排債券發行。"}]', '{"verb":"broker","noun":"brokerage"}', NULL, 2, 801, 831),
(802, 'brokerage', '/ˈbroʊkərɪdʒ/', 'noun', '{"zh-TW":["經紀公司；佣金"],"en":["a firm that buys and sells securities on behalf of clients; also the fee charged"]}', NULL, 'brokerage firm / open a brokerage account / brokerage fee / online brokerage', '[{"en":"She moved her investments to an online brokerage to reduce fees.","zh-TW":"她將投資轉移到網路經紀公司以降低費用。"},{"en":"The brokerage charged a $10 commission per trade.","zh-TW":"該經紀公司每筆交易收取10美元佣金。"}]', '{"noun":"broker","verb":"broker"}', NULL, 3, 802, NULL),
(803, 'brokerage fee', '/ˈbroʊkərɪdʒ fiː/', 'noun', '{"zh-TW":["經紀費；佣金費"],"en":["a commission paid to a broker for arranging a financial transaction"]}', NULL, 'pay a brokerage fee / brokerage fee structure', '[{"en":"The real estate brokerage fee was 3% of the final sale price.","zh-TW":"房地產經紀費為最終成交價格的3%。"},{"en":"Online platforms have reduced brokerage fees for small retail investors.","zh-TW":"在線平台降低了小型零售投資者的經紀費。"}]', '{"noun":"broker"}', NULL, 5, 803, NULL),
(804, 'brook', '/brʊk/', 'verb, noun', '{"zh-TW":["【主要意義-名詞】小溪；小河","【次要意義-動詞】容忍；忍受（常用於否定句）"],"en":["[primary - noun] a small stream","[secondary - verb] to tolerate or allow, usually in negative constructions"]}', NULL, 'brook no delay / brook no interference / will not brook', '[{"en":"The CEO will brook no interference in his decision-making process.","zh-TW":"執行長不會容忍任何對其決策過程的干涉。"},{"en":"The new regulations brook no exceptions for established companies.","zh-TW":"新法規對老牌企業不容任何例外。"},{"en":"She brooked no nonsense from her subordinates.","zh-TW":"她不容許下屬有任何胡鬧行為。"}]', NULL, '動詞 brook 幾乎只出現在否定句中（brook no + noun），意為「不容忍」，是正式書面英語常見用法，TOEIC 閱讀中出現時常讓考生誤認為名詞小溪。', 2, 804, NULL),
(805, 'broth', '/brɒθ/', 'noun', '{"zh-TW":["高湯；清湯"],"en":["a thin soup made from meat or vegetables"]}', NULL, 'chicken broth / vegetable broth', '[{"en":"A bowl of hot broth is comforting on a cold day.","zh-TW":"寒冷的天氣裡，一碗熱高湯令人感到溫暖。"},{"en":"The chef used a rich beef broth as the base for the soup.","zh-TW":"廚師用濃郁的牛肉高湯作為湯的基底。"}]', NULL, NULL, 2, 805, NULL),
(806, 'brother', '/ˈbrʌðər/', 'noun', '{"zh-TW":["兄弟"],"en":["a male sibling"]}', NULL, 'big brother / brother-in-law', '[{"en":"My brother is older than me.","zh-TW":"我哥哥比我大。"},{"en":"They treat each other like brothers.","zh-TW":"他們像兄弟一樣對待彼此。"}]', '{"noun2":"brotherhood"}', NULL, 3, 806, NULL),
(807, 'brown', '/braʊn/', 'adjective', '{"zh-TW":["棕色的"],"en":["the color of wood or earth"]}', NULL, 'brown sugar / brown bag', '[{"en":"She has brown eyes.","zh-TW":"她有棕色的眼睛。"},{"en":"The leaves turn brown in autumn.","zh-TW":"秋天葉子變成棕色。"}]', NULL, NULL, 2, 807, NULL),
(808, 'browse', '/braʊz/', 'verb', '{"zh-TW":["瀏覽；隨意看看"],"en":["to look at things casually without intent to buy"]}', '{"root":{"text":"browse","meaning":"young shoots (嫩芽)"},"logic":"原指動物啃食嫩芽，後引申為隨意翻閱。"}', 'browse through / browse the internet', '[{"en":"I spent an hour browsing in the bookstore.","zh-TW":"我在書店裡瀏覽了一個小時。"},{"en":"She likes to browse online shops during lunch.","zh-TW":"她喜歡午餐時瀏覽網路商店。"}]', '{"noun":"browser"}', NULL, 2, 808, NULL),
(809, 'browser', '/ˈbraʊzər/', 'noun', '{"zh-TW":["瀏覽器"],"en":["a program for accessing websites"]}', NULL, 'web browser / browser history', '[{"en":"Which web browser do you use?","zh-TW":"你使用哪個網頁瀏覽器？"},{"en":"Clear your browser history.","zh-TW":"清除你的瀏覽記錄。"}]', '{"verb":"browse"}', NULL, 3, 809, NULL),
(810, 'brunch', '/brʌntʃ/', 'noun', '{"zh-TW":["早午餐"],"en":["a late morning meal combining breakfast and lunch"]}', NULL, 'weekend brunch / brunch menu', '[{"en":"The hotel serves a popular weekend brunch.","zh-TW":"飯店供應受歡迎的週末早午餐。"},{"en":"We went out for brunch after the morning meeting.","zh-TW":"早上的會議結束後我們出去吃早午餐。"}]', NULL, NULL, 2, 810, NULL),
(811, 'brush', '/brʌʃ/', 'noun', '{"zh-TW":["刷子；刷"],"en":["a tool with bristles for cleaning or painting"]}', NULL, 'tooth brush / brush up on', '[{"en":"Brush your teeth twice a day.","zh-TW":"每天刷牙兩次。"},{"en":"I need to brush up on my French.","zh-TW":"我需要複習一下法語。"}]', '{"verb":"brush"}', NULL, 2, 811, NULL),
(812, 'budget', '/ˈbʌdʒɪt/', 'noun', '{"zh-TW":["預算"],"en":["an estimate of income and expenditure for a set period"]}', '{"root":{"text":"bougette","meaning":"small bag (小袋子)"},"logic":"裝錢的小袋子（分配金額），即「預算」。"}', 'within budget / over budget / annual budget', '[{"en":"The project was completed within budget.","zh-TW":"專案在預算內完成。"},{"en":"We need to cut the budget by 10%.","zh-TW":"我們需要削減10%的預算。"}]', '{"adjective":"budgetary"}', NULL, 2, 812, 13),
(813, 'budget approval', '/ˈbʌdʒɪt əˈpruːvəl/', 'noun', '{"zh-TW":["預算批准"],"en":["the formal authorization of a budget by appropriate management"]}', NULL, 'obtain budget approval / budget approval process', '[{"en":"All projects require budget approval before commencement.","zh-TW":"所有項目在開始前都需要預算批准。"},{"en":"Budget approval for the capital project was granted by the board.","zh-TW":"資本項目的預算批准由董事會授予。"}]', NULL, NULL, 5, 813, NULL),
(814, 'budget cycle', '/ˈbʌdʒɪt ˈsaɪkəl/', 'noun', '{"zh-TW":["預算週期"],"en":["the recurring process of preparing, approving, and managing annual budgets"]}', NULL, 'manage the budget cycle / start of the budget cycle', '[{"en":"The budget cycle begins in September for the next fiscal year.","zh-TW":"預算週期從九月開始，為下一財政年度做準備。"},{"en":"All departments must submit proposals early in the budget cycle.","zh-TW":"所有部門必須在預算週期早期提交提案。"}]', NULL, NULL, 4, 814, NULL),
(815, 'budget forecast', '/ˈbʌdʒɪt ˈfɔːrkæst/', 'noun', '{"zh-TW":["預算預測"],"en":["an estimate of future income and spending"]}', NULL, 'prepare a budget forecast / review the budget forecast', '[{"en":"The budget forecast projected a 10% increase in revenue.","zh-TW":"預算預測預計收入增長10%。"},{"en":"Management revised the budget forecast after the market downturn.","zh-TW":"在市場下行後，管理層修訂了預算預測。"}]', NULL, NULL, 5, 815, NULL),
(816, 'budget proposal', '/ˈbʌdʒɪt prəˈpəʊzəl/', 'noun', '{"zh-TW":["預算提案"],"en":["a plan submitted for approval listing expected income and expenses"]}', NULL, 'submit a budget proposal / annual budget proposal', '[{"en":"The department submitted its budget proposal for next year.","zh-TW":"部門提交了明年的預算提案。"},{"en":"The budget proposal was approved by the finance committee.","zh-TW":"預算提案獲得了財務委員會批准。"}]', NULL, NULL, 5, 816, NULL),
(817, 'budget variance', '/ˈbʌdʒɪt ˈveəriəns/', 'noun', '{"zh-TW":["預算差異"],"en":["the difference between budgeted and actual financial results"]}', NULL, 'analyze budget variance / explain budget variance', '[{"en":"A 10% favorable budget variance was reported in Q2.","zh-TW":"第二季度報告了10%的有利預算差異。"},{"en":"Budget variance reports are reviewed monthly by department heads.","zh-TW":"預算差異報告每月由部門主管審查。"}]', NULL, NULL, 5, 817, NULL),
(818, 'buffer', '/ˈbʌfər/', 'noun', '{"zh-TW":["緩衝；備用時間"],"en":["a reserve of time or resources included to handle unexpected issues"]}', NULL, 'time buffer / budget buffer / add a buffer / contingency buffer', '[{"en":"A two-week buffer was added to the schedule for unexpected delays.","zh-TW":"排程增加了兩週的緩衝時間以應對意外延遲。"},{"en":"Budget buffers protect projects from cost overruns.","zh-TW":"預算緩衝保護項目免受成本超支。"}]', '{"verb":"buffer","adjective":"buffered"}', NULL, 2, 818, NULL),
(819, 'buffet', '/ˈbʊfeɪ/', 'noun', '{"zh-TW":["自助餐"],"en":["a meal where guests serve themselves from a variety of dishes"]}', NULL, 'breakfast buffet / buffet style', '[{"en":"The Sunday brunch buffet is very popular.","zh-TW":"週日早午餐自助餐非常受歡迎。"},{"en":"The buffet includes over thirty different dishes.","zh-TW":"自助餐包含三十多種不同菜餚。"}]', NULL, NULL, 2, 819, NULL),
(820, 'build', '/bɪld/', 'verb', '{"zh-TW":["建造；建立"],"en":["to construct","to develop over time","to make something by putting parts together"]}', NULL, 'build up / build a team; build up / build on', '[{"en":"We need to build a strong team.","zh-TW":"我們需要建立一支強大的團隊。"},{"en":"They are building a new factory.","zh-TW":"他們正在建造一座新工廠。"},{"en":"They''re building a new house.","zh-TW":"他們正在建一棟新房子。"},{"en":"We need to build trust.","zh-TW":"我們需要建立信任。"}]', '{"verb":"build","noun":"building","noun2":"builder"}', NULL, 2, 820, NULL),
(821, 'building code', '/ˈbɪldɪŋ kəʊd/', 'noun', '{"zh-TW":["建築法規"],"en":["regulations specifying standards for construction"]}', NULL, 'comply with building codes / building code violation', '[{"en":"All renovations must comply with local building codes.","zh-TW":"所有翻新工程必須符合當地建築法規。"},{"en":"The inspection found several building code violations.","zh-TW":"檢查發現了幾項建築法規違規行為。"}]', NULL, NULL, 5, 821, NULL),
(822, 'building permit', '/''bɪldɪŋ ˌpɜːrmɪt/', 'noun', '{"zh-TW":["建築許可證；施工許可"],"en":["official permission from a local authority to construct or alter a building"]}', NULL, 'obtain a building permit / apply for a building permit / building permit required', '[{"en":"A building permit is required before starting any major construction work.","zh-TW":"在開始任何主要建築工程之前需要獲得建築許可證。"},{"en":"The renovation was halted because the contractor hadn''t obtained a building permit.","zh-TW":"翻新工程被叫停，因為承包商沒有獲得建築許可證。"}]', NULL, NULL, 5, 822, NULL),
(823, 'built-up area', '/''bɪlt ʌp ˌeəriə/', 'noun', '{"zh-TW":["建成區；市區"],"en":["an area that has been extensively developed with buildings and infrastructure"]}', NULL, 'busy built-up area / dense built-up area / expand into built-up areas', '[{"en":"The accident occurred in a busy built-up area where speed limits are low.","zh-TW":"事故發生在一個繁忙的建成區，那裡的限速很低。"},{"en":"Property prices in built-up areas tend to be significantly higher than rural locations.","zh-TW":"建成區的房產價格往往比農村地區高得多。"}]', NULL, NULL, 5, 823, NULL),
(824, 'bulk', '/bʌlk/', 'noun', '{"zh-TW":["大量；大批","體積"],"en":["a large quantity or mass","a large quantity","the mass or size of something"]}', '{"root":{"text":"bulk","meaning":"heap (堆)"},"logic":"大堆的量，即「大量」。"}', 'in bulk / bulk order / bulk purchase', '[{"en":"Ordering in bulk reduces the unit cost.","zh-TW":"大量訂購可降低單位成本。"},{"en":"The bulk of our revenue comes from overseas.","zh-TW":"我們大部分營收來自海外。"},{"en":"Buying in bulk saves money.","zh-TW":"大量採購可以省錢。"},{"en":"The bulk of the work has been completed.","zh-TW":"大部分的工作已經完成。"}]', '{"adjective":"bulky"}', NULL, 1, 824, 832),
(825, 'bulk buying', '/bʌlk ˈbaɪɪŋ/', 'noun', '{"zh-TW":["批量採購；大量購買"],"en":["purchasing goods in large quantities, often to obtain a lower unit price"]}', NULL, 'engage in bulk buying / bulk buying discount', '[{"en":"Bulk buying reduced per-unit cost and improved margins.","zh-TW":"批量採購降低了每單位成本並改善了利潤率。"},{"en":"The co-operative leverages bulk buying power for its members.","zh-TW":"合作社為其成員利用批量採購能力。"}]', '{"synonym":"volume purchasing","synonym2":"bulk purchasing"}', NULL, 4, 825, NULL),
(826, 'bulk cargo', '/bʌlk ˈkɑːrɡoʊ/', 'noun', '{"zh-TW":["散裝貨物"],"en":["unpackaged goods transported in large quantities such as grain or oil"]}', NULL, 'transport bulk cargo / bulk cargo vessel', '[{"en":"The port handled 50 million tonnes of bulk cargo last year.","zh-TW":"港口去年處理了5000萬噸散裝貨物。"},{"en":"Bulk cargo ships are designed to carry large volumes efficiently.","zh-TW":"散裝貨船設計用於高效運載大量貨物。"}]', '{"synonym":"dry bulk","synonym2":"wet bulk"}', NULL, 4, 826, NULL),
(827, 'bulk discount', '/bʌlk ˈdɪskaʊnt/', 'noun', '{"zh-TW":["批量折扣"],"en":["a price reduction granted when goods are purchased in large quantities"]}', NULL, 'offer a bulk discount / bulk discount rate', '[{"en":"A 15% bulk discount was applied to orders over 500 units.","zh-TW":"訂購超過500個單位時適用15%的批量折扣。"},{"en":"Bulk discounts incentivize larger orders and improve supply efficiency.","zh-TW":"批量折扣激勵了更大的訂單並提高了供應效率。"}]', NULL, NULL, 5, 827, NULL),
(828, 'bulk order', '/bʌlk ˈɔːrdər/', 'noun', '{"zh-TW":["大宗訂購；批量訂單"],"en":["an order for a large quantity of goods at once"]}', NULL, 'place a bulk order / bulk order discount', '[{"en":"We placed a bulk order to take advantage of the discount.","zh-TW":"我們下了大宗訂單以享受折扣優惠。"},{"en":"Bulk orders are typically processed with a longer lead time.","zh-TW":"大宗訂單通常有較長的前置時間。"}]', NULL, NULL, 4, 828, NULL),
(829, 'bulk purchase', '/bʌlk ˈpɜːrtʃəs/', 'noun', '{"zh-TW":["批量採購；大量購買"],"en":["buying large quantities at a reduced per-unit price"]}', NULL, 'place a bulk purchase / benefit from bulk purchase', '[{"en":"A bulk purchase of office supplies cut unit costs by 25%.","zh-TW":"批量採購辦公用品使單位成本降低了25%。"},{"en":"The company negotiated a bulk purchase agreement for raw materials.","zh-TW":"公司為原材料談判了批量採購協議。"}]', NULL, NULL, 5, 829, NULL),
(830, 'bull market', '/bʊl ˈmɑːrkɪt/', 'noun', '{"zh-TW":["多頭市場；牛市"],"en":["a period of rising stock prices and investor confidence"]}', NULL, 'in a bull market / bull market rally / start of a bull market', '[{"en":"The bull market lasted five years before the correction.","zh-TW":"牛市在調整前持續了五年。"},{"en":"Investors thrived during the long bull market.","zh-TW":"投資者在漫長的牛市中蓬勃發展。"}]', '{"antonym":"bear market"}', NULL, 4, 830, NULL),
(831, 'bullet point', '/ˈbʊlɪt pɔɪnt/', 'noun', '{"zh-TW":["項目符號；要點"],"en":["a symbol used to introduce items in a list"]}', NULL, 'use bullet points / list with bullet points', '[{"en":"Use bullet points to summarize key findings.","zh-TW":"使用項目符號來總結關鍵發現。"},{"en":"The presenter highlighted each bullet point on the slide.","zh-TW":"演講者強調了投影片上的每個要點。"}]', NULL, NULL, 4, 831, NULL),
(832, 'bulletin', 'ˈbʊlɪtɪn', 'noun', '{"zh-TW":["公告；快訊","簡報"],"en":["a short official notice","a newsletter"]}', NULL, 'bulletin board/news bulletin', '[{"en":"Check the bulletin board for updates.","zh-TW":"查看公告欄以獲取更新。"}]', NULL, NULL, 3, 832, NULL),
(833, 'bulletin board', '/ˈbʊlɪtɪn bɔːrd/', 'noun', '{"zh-TW":["公告欄；布告板"],"en":["a surface on which notices are posted; also an electronic posting area"]}', NULL, 'post on the bulletin board / check the bulletin board', '[{"en":"Job vacancies are posted on the company bulletin board.","zh-TW":"職缺在公司公告欄上張貼。"},{"en":"The digital bulletin board displays real-time production metrics.","zh-TW":"數位公告欄顯示實時生產指標。"}]', NULL, NULL, 5, 833, NULL),
(834, 'bundling', '/ˈbʌndəlɪŋ/', 'noun', '{"zh-TW":["捆綁銷售；組合定價"],"en":["selling multiple products or services together as a package at a combined price"]}', NULL, 'product bundling / bundling strategy / price bundling', '[{"en":"Bundling software with hardware increased average order value.","zh-TW":"將軟體與硬體捆綁銷售提高了平均訂單價值。"},{"en":"Streaming services use bundling to reduce churn.","zh-TW":"串流服務使用捆綁銷售來降低流失率。"}]', '{"verb":"bundle"}', NULL, 3, 834, NULL),
(835, 'burden', '/ˈbɜːrdn/', 'noun', '{"zh-TW":["負擔；重擔"],"en":["a heavy load; a duty or responsibility that causes worry","a heavy load; a duty that causes worry"]}', '{"root":{"text":"burden","meaning":"carry (攜帶)"},"logic":"需要攜帶的重量，即「負擔」。"}', 'financial burden / burden on / ease the burden; heavy burden / financial burden / burden of proof', '[{"en":"The new regulations place a heavy burden on small businesses.","zh-TW":"新法規對小企業造成沉重負擔。"},{"en":"Tax cuts helped ease the financial burden on families.","zh-TW":"減稅幫助減輕了家庭的經濟負擔。"},{"en":"The tax increase places a burden on families.","zh-TW":"增稅對家庭造成負擔。"},{"en":"She didn''t want to be a burden to her children.","zh-TW":"她不想成為孩子的負擔。"}]', '{"adjective":"burdensome","verb":"burden"}', NULL, 2, 835, NULL),
(836, 'bureau', '/ˈbjʊərəʊ/', 'noun', '{"zh-TW":["局；署；辦公室"],"en":["a government department or agency","an office for business"]}', '{"root":{"text":"bureau","meaning":"desk/office (桌子/辦公室)"},"logic":"辦公的地方，即「局、署」。"}', 'travel bureau / bureau of statistics', '[{"en":"The Bureau of Labor Statistics released new employment data.","zh-TW":"勞動統計局發布了新的就業數據。"},{"en":"Contact the information bureau for details.","zh-TW":"詳情請聯繫資訊服務處。"}]', '{"noun":"bureaucracy","adjective":"bureaucratic"}', NULL, 2, 836, NULL),
(837, 'bureaucracy', '/bjʊˈrɒkrəsi/', 'noun', '{"zh-TW":["官僚體制；繁文縟節"],"en":["a system of government with many complicated rules"]}', '{"root":{"text":"bureau","meaning":"office (辦公室)"},"suffix":{"text":"-cracy","meaning":"rule (統治)"},"logic":"辦公室統治，即「官僚體制」。"}', 'government bureaucracy / red tape and bureaucracy', '[{"en":"Excessive bureaucracy slows down the approval process.","zh-TW":"過度的官僚體制拖慢了審批流程。"},{"en":"The company reduced internal bureaucracy to improve efficiency.","zh-TW":"公司減少了內部繁文縟節以提高效率。"}]', '{"adjective":"bureaucratic"}', NULL, 4, 837, NULL),
(838, 'burn', '/bɜːrn/', 'verb', '{"zh-TW":["燃燒；燒傷"],"en":["to be on fire; to damage with heat"]}', NULL, 'burn down / burn out', '[{"en":"The candle burned all night.","zh-TW":"蠟燭燃燒了整夜。"},{"en":"She burned her hand on the stove.","zh-TW":"她的手被爐子燙傷了。"}]', NULL, NULL, 1, 838, NULL),
(839, 'burn rate', '/bɜːrn reɪt/', 'noun', '{"zh-TW":["燒錢速度；現金消耗率"],"en":["the rate at which a startup spends its cash reserves"]}', NULL, 'monthly burn rate / control burn rate / reduce burn rate', '[{"en":"The startup''s burn rate was $200,000 per month.","zh-TW":"新創公司每月的現金消耗率為20萬美元。"},{"en":"Investors closely monitor burn rate to ensure sufficient runway.","zh-TW":"投資者密切監控燒錢速度以確保足夠的資金跑道。"}]', NULL, NULL, 3, 839, NULL),
(840, 'burndown chart', '/ˈbɜːrndaʊn tʃɑːrt/', 'noun', '{"zh-TW":["燃盡圖"],"en":["a graphical representation of work remaining versus time in a sprint"]}', NULL, 'create a burndown chart / read the burndown chart / sprint burndown chart', '[{"en":"The burndown chart showed the team was ahead of schedule.","zh-TW":"燃盡圖顯示團隊超前於計劃。"},{"en":"A flat burndown chart indicates work is not being completed.","zh-TW":"平坦的燃盡圖表明工作沒有被完成。"}]', NULL, NULL, 5, 840, NULL),
(841, 'burnout', '/ˈbɜːrnaʊt/', 'noun', '{"zh-TW":["職業倦怠；過度疲勞"],"en":["exhaustion caused by prolonged overwork or stress"]}', NULL, 'prevent burnout / employee burnout / recover from burnout', '[{"en":"The company introduced wellness programs to prevent burnout.","zh-TW":"公司引入健康計劃以防止職業倦怠。"},{"en":"She took a leave of absence due to burnout.","zh-TW":"她因職業倦怠而請了假。"}]', NULL, NULL, 3, 841, NULL),
(842, 'burst', '/bɜːrst/', 'verb', '{"zh-TW":["爆裂；突然發生"],"en":["to break open suddenly"]}', NULL, 'burst into tears / burst out laughing', '[{"en":"The balloon burst.","zh-TW":"氣球爆了。"},{"en":"She burst into tears.","zh-TW":"她突然哭了起來。"}]', NULL, NULL, 2, 842, NULL),
(843, 'bus', '/bʌs/', 'noun', '{"zh-TW":["公車"],"en":["a large vehicle carrying passengers"]}', NULL, 'bus stop / miss the bus', '[{"en":"I take the bus to work.","zh-TW":"我搭公車上班。"},{"en":"We missed the last bus.","zh-TW":"我們錯過了末班車。"}]', NULL, NULL, 1, 843, NULL),
(844, 'business card', '/ˈbɪznɪs kɑːrd/', 'noun', '{"zh-TW":["名片"],"en":["a small card with personal and contact information"]}', NULL, 'exchange business cards / print business cards', '[{"en":"He exchanged business cards with the potential client.","zh-TW":"他與潛在客戶交換了名片。"},{"en":"Always bring plenty of business cards to conferences.","zh-TW":"參加會議時務必帶足名片。"}]', NULL, NULL, 5, 844, NULL),
(845, 'business case', '/ˈbɪznɪs keɪs/', 'noun', '{"zh-TW":["商業論證；業務案例"],"en":["a documented justification for undertaking a project or investment"]}', NULL, 'prepare a business case / business case approval', '[{"en":"A business case was prepared to justify the new warehouse investment.","zh-TW":"為論證新倉庫投資的合理性而準備了業務案例。"},{"en":"The business case included financial projections and risk assessment.","zh-TW":"業務案例包括了財務預測和風險評估。"}]', NULL, NULL, 5, 845, NULL),
(846, 'business class', '/ˈbɪznɪs klæs/', 'noun', '{"zh-TW":["商務艙"],"en":["a travel class between economy and first class"]}', NULL, 'fly business class / upgrade to business class', '[{"en":"She was upgraded to business class on the long-haul flight.","zh-TW":"她在長途飛行中升級到商務艙。"},{"en":"Business class passengers enjoy wider seats.","zh-TW":"商務艙乘客享有更寬的座位。"}]', NULL, NULL, 5, 846, NULL),
(847, 'business continuity', '/ˈbɪznəs kənˈtɪnjuɪti/', 'noun', '{"zh-TW":["業務連續性"],"en":["the ability of an organization to continue operations during a disruption"]}', NULL, 'business continuity plan / ensure business continuity', '[{"en":"The disaster recovery plan ensures business continuity during outages.","zh-TW":"災難恢復計劃確保中斷期間的業務連續性。"},{"en":"Business continuity was maintained thanks to the backup systems.","zh-TW":"由於備份系統的存在，業務連續性得以維持。"}]', NULL, NULL, 5, 847, NULL),
(848, 'business continuity plan', '/ˈbɪznɪs kənˌtɪnjuːɪti plæn/', 'noun', '{"zh-TW":["業務持續計劃"],"en":["a strategy to ensure critical business functions continue during a disaster"]}', NULL, 'activate the business continuity plan / business continuity plan testing', '[{"en":"The company tested its business continuity plan with a simulated outage.","zh-TW":"公司通過模擬中斷測試了業務持續計劃。"},{"en":"A business continuity plan reduces downtime and financial loss.","zh-TW":"業務持續計劃減少了停機時間和財務損失。"}]', '{"abbreviation":"BCP"}', NULL, 5, 848, NULL),
(849, 'business cycle', '/ˈbɪznɪs ˈsaɪkəl/', 'noun', '{"zh-TW":["商業週期；景氣循環"],"en":["the recurring pattern of economic expansion and contraction over time"]}', NULL, 'stage of the business cycle / manage through the business cycle / business cycle theory', '[{"en":"Investors adjust their portfolio allocation based on the current stage of the business cycle.","zh-TW":"投資者根據商業週期的當前階段調整其投資組合配置。"},{"en":"Monetary and fiscal policy tools are used to moderate the peaks and troughs of the business cycle.","zh-TW":"貨幣和財政政策工具被用來緩和商業週期的峰值和谷值。"}]', NULL, NULL, 5, 849, NULL);